def solve(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0

    # Find separator rows/cols: fully filled with the same non-zero value.
    sep_rows = []
    sep_cols = []
    sep_color = None

    for r in range(h):
        v = grid[r][0]
        if v != 0 and all(grid[r][c] == v for c in range(w)):
            sep_rows.append(r)
            sep_color = v

    for c in range(w):
        v = grid[0][c]
        if v != 0 and all(grid[r][c] == v for r in range(h)):
            sep_cols.append(c)
            sep_color = v if sep_color is None else sep_color

    if sep_color is None:
        # Fallback: no separators detected
        return [row[:] for row in grid]

    # Find the active color (non-zero, non-separator)
    active_color = None
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0 and v != sep_color:
                active_color = v
                break
        if active_color is not None:
            break

    if active_color is None:
        return [row[:] for row in grid]

    # Build row/col block ranges between separators.
    row_blocks = []
    start = 0
    sep_set_r = set(sep_rows)
    for r in range(h + 1):
        if r == h or r in sep_set_r:
            if start < r:
                row_blocks.append((start, r))
            start = r + 1

    col_blocks = []
    start = 0
    sep_set_c = set(sep_cols)
    for c in range(w + 1):
        if c == w or c in sep_set_c:
            if start < c:
                col_blocks.append((start, c))
            start = c + 1

    # Count active-color cells in each block.
    counts = []
    max_count = 0
    for rb in row_blocks:
        row_counts = []
        for cb in col_blocks:
            cnt = 0
            for r in range(rb[0], rb[1]):
                for c in range(cb[0], cb[1]):
                    if grid[r][c] == active_color:
                        cnt += 1
            row_counts.append(cnt)
            if cnt > max_count:
                max_count = cnt
        counts.append(row_counts)

    # Create output: keep separators, clear other blocks, fill maximal blocks.
    out = [row[:] for row in grid]

    # Clear all non-separator, non-selected cells to 0 first.
    for r in range(h):
        for c in range(w):
            if r not in sep_set_r and c not in sep_set_c:
                out[r][c] = 0

    # Fill blocks whose count equals the maximum (and max > 0).
    if max_count > 0:
        for i, rb in enumerate(row_blocks):
            for j, cb in enumerate(col_blocks):
                if counts[i][j] == max_count:
                    for r in range(rb[0], rb[1]):
                        for c in range(cb[0], cb[1]):
                            out[r][c] = active_color

    return out

